function validate([nums, head]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value of nums is between 1 and 100000.';
  const banned = new Set(nums);
  if (banned.size !== nums.length) return 'The values in nums must be distinct.';
  if (!Array.isArray(head) || head.length < 1 || head.length > 100000) return 'The list needs 1 to 100000 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each node value is between 1 and 100000.';
  if (head.every(v => banned.has(v))) return 'At least one node must keep a value that is not in nums.';
  return null;
}

